<template>
  <div class="space-y-6">
    <div class="flex flex-wrap justify-end gap-2"><UButton :href="`${endpoint}/export?kind=profit`" external variant="outline" icon="i-lucide-download">Export profit report</UButton><UButton :href="`${endpoint}/export?kind=costs`" external variant="outline" icon="i-lucide-download">Export costs</UButton><UButton :href="`${endpoint}/export?kind=finance`" external variant="outline" icon="i-lucide-download">Export ledger</UButton></div>
    <UAlert color="info" title="Profit and cash are separate" :description="event.status === 'completed' ? 'Event result before income tax. Supplier taxes are included in costs; input-tax credits are not assumed. Collections and unpaid bills are shown separately.' : 'Provisional event result includes active booking charges and all committed supplier costs. Forecast also allows for the remaining budget. Complete the event after reconciling bookings and costs.'" />
    <div class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><MetricCard v-for="metric in metrics" :key="metric.label" :label="metric.label" :value="formatMinor(metric.value)" :description="metric.description" icon="i-lucide-chart-no-axes-combined" /></div>
    <UCard><template #header><h3 class="font-semibold">Budget and performance</h3></template><dl class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><div v-for="metric in budgetMetrics" :key="metric.label"><dt class="text-sm text-slate-500">{{ metric.label }}</dt><dd class="mt-1 font-semibold">{{ metric.value }}</dd></div></dl><p class="mt-4 text-xs text-slate-500">Break-even uses the current attendee mix and budgeted variable cost per person. Supplier tax is included in costs; registration tax is excluded from revenue. Cash surplus includes tax still to be settled.</p></UCard>
    <div class="grid items-start gap-6 xl:grid-cols-2">
      <UCard><template #header><h3 class="font-semibold">Record a transaction</h3></template><form class="finance-form grid gap-4 sm:grid-cols-2" @submit.prevent="saveTransaction">
        <label>Type<select v-model="transaction.kind" @change="resetLinks"><option v-for="kind in transactionKinds" :key="kind.value" :value="kind.value">{{ kind.label }}</option></select></label>
        <label>Amount including tax ({{ event.currency }})<input v-model.number="transaction.amount" required type="number" min="0.01" step="0.01"></label>
        <label v-if="isBooking" class="sm:col-span-2">Booking<select v-model.number="transaction.bookingId" required @change="transaction.sourceId = null"><option :value="null" disabled>Select booking</option><option v-for="booking in bookings" :key="booking.id" :value="booking.id">{{ booking.reference }} · {{ booking.attendees[0]?.name }} · due {{ formatMinor(booking.balance.outstanding) }} · credit {{ formatMinor(booking.balance.credit) }}</option></select></label>
        <label v-if="isCost" class="sm:col-span-2">Supplier cost<select v-model.number="transaction.costId" required @change="transaction.sourceId = null"><option :value="null" disabled>Select supplier cost</option><option v-for="supplierCost in costs" :key="supplierCost.id" :value="supplierCost.id">{{ supplierCost.supplier }} · {{ supplierCost.description }} · due {{ formatMinor(costDue(supplierCost)) }}</option></select></label>
        <label v-if="isRefund" class="sm:col-span-2">Original payment<select v-model.number="transaction.sourceId" required><option :value="null" disabled>Select original payment</option><option v-for="row in refundSources" :key="row.id" :value="row.id">{{ row.receiptNumber }} · remaining {{ formatMinor(refundable(row)) }}</option></select></label>
        <label v-if="transaction.kind === 'income'">Tax included in amount<input v-model.number="transaction.tax" type="number" min="0" step="0.01" required></label>
        <label>Payment method<select v-model="transaction.method"><option v-for="method in ['cash', 'upi', 'bank_transfer', 'card', 'cheque', 'other']" :key="method" :value="method">{{ method.replaceAll('_', ' ') }}</option></select></label><label>Date received / refunded<input v-model="transaction.occurredOn" required type="date" :max="today"></label><label>Bank / cheque / UPI reference<input v-model="transaction.reference" maxlength="250"></label><label class="sm:col-span-2">Description / refund reason<input v-model="transaction.description" required maxlength="2000"></label>
        <p class="text-xs text-slate-500 sm:col-span-2">Record funds only after receipt or settlement. To correct an entry, refund the original and record a replacement; receipts are preserved.</p>
        <UAlert v-if="transactionError" class="sm:col-span-2" color="error" :title="transactionError" /><div><UButton type="submit" :loading="savingTransaction">Record transaction</UButton></div>
      </form></UCard>
      <UCard><template #header><h3 class="font-semibold">{{ editingCostId ? 'Correct supplier cost' : 'Add a supplier cost' }}</h3></template><form class="finance-form grid gap-4 sm:grid-cols-2" @submit.prevent="saveCost"><label>Supplier<input v-model="cost.supplier" required maxlength="250"></label><label>Category<select v-model="cost.category"><option value="direct">Direct event cost</option><option value="overhead">Other expense / overhead</option></select></label><label class="sm:col-span-2">Description<input v-model="cost.description" required maxlength="1000" placeholder="Hotel, catering, bus, instructor, awards…"></label><label>Amount before tax<input v-model.number="cost.amount" type="number" min="0" step="0.01" required></label><label>Supplier tax<input v-model.number="cost.tax" type="number" min="0" step="0.01" required></label><label>Cost status<select v-model="cost.status"><option value="committed">Committed / ordered</option><option value="incurred">Incurred / delivered</option></select></label><label>Due date<input v-model="cost.dueDate" type="date"></label><label>Invoice number<input v-model="cost.invoiceNumber" maxlength="250"></label><label>Notes<input v-model="cost.notes" maxlength="3000"></label><UAlert v-if="costError" class="sm:col-span-2" color="error" :title="costError" /><div><UButton type="submit" :loading="savingCost">{{ editingCostId ? 'Save cost' : 'Add cost' }}</UButton><UButton v-if="editingCostId" type="button" variant="ghost" color="neutral" @click="cancelCostEdit">Cancel edit</UButton></div></form></UCard>
    </div>
    <UCard><template #header><h3 class="font-semibold">Supplier costs and balances</h3></template><div v-if="costs.length" class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr><th>Supplier / cost</th><th>Category / status</th><th>Total</th><th>Due</th><th>Actions</th></tr></thead><tbody><tr v-for="item in costs" :key="item.id"><td><p class="font-medium">{{ item.supplier }}</p><p>{{ item.description }}</p><p class="text-xs text-slate-500">{{ item.invoiceNumber }} {{ item.dueDate ? `· due ${item.dueDate}` : '' }}</p></td><td>{{ item.category }}<br>{{ item.status }}</td><td>{{ formatMinor(item.amount + item.tax) }}</td><td>{{ item.status === 'cancelled' ? '—' : formatMinor(costDue(item)) }}</td><td><div class="flex flex-wrap gap-2"><UButton v-if="item.status !== 'cancelled'" size="xs" variant="outline" @click="startCostEdit(item)">Edit</UButton><UButton v-if="item.status === 'committed'" size="xs" variant="soft" :loading="busyCost === item.id" @click="setCostStatus(item.id, 'incurred')">Mark incurred</UButton><UButton v-if="item.status !== 'cancelled'" size="xs" color="neutral" variant="ghost" :loading="busyCost === item.id" @click="setCostStatus(item.id, 'cancelled')">Cancel cost</UButton></div></td></tr></tbody></table></div><p v-else class="text-sm text-slate-500">No supplier costs recorded yet.</p></UCard>
    <UCard><template #header><h3 class="font-semibold">Transaction ledger</h3></template><div v-if="ledger.length" class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr><th>Date</th><th>Type / receipt</th><th>Description</th><th>Amount</th><th>Method</th><th>Receipt</th></tr></thead><tbody><tr v-for="row in ledger" :key="row.id"><td>{{ row.occurredOn }}</td><td>{{ row.kind.replaceAll('_', ' ') }}<p class="text-xs text-slate-500">{{ row.receiptNumber }}</p></td><td>{{ row.description }}</td><td>{{ formatMinor(row.amount) }}</td><td>{{ row.method }}<p class="text-xs">{{ row.reference }}</p></td><td><a :href="`${endpoint}/receipt?transactionId=${row.id}`" class="text-primary underline" target="_blank" rel="noopener">PDF</a></td></tr></tbody></table></div><p v-else class="text-sm text-slate-500">Payments, refunds and supplier settlements will appear here.</p></UCard>
  </div>
</template>
<script setup lang="ts">
const props = defineProps<{ event: any, finances: any, bookings: any[], costs: any[], ledger: any[], endpoint: string, initialBookingId?: number | null }>()
const emit = defineEmits(['changed'])
const toast = useToast()
const { formatMinor } = useMoney(() => props.event.currency)
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' })
const transactionKinds = [{ value: 'payment', label: 'Family payment' }, { value: 'refund', label: 'Family refund' }, { value: 'income', label: 'Sponsorship / other income' }, { value: 'income_refund', label: 'Refund other income' }, { value: 'cost_payment', label: 'Supplier payment' }, { value: 'cost_refund', label: 'Supplier refund received' }]
const blankTransaction = () => ({ requestKey: crypto.randomUUID(), kind: 'payment', amount: props.initialBookingId ? (props.bookings.find(booking => booking.id === props.initialBookingId)?.balance.outstanding || 0) / 100 : 0, tax: 0, bookingId: props.initialBookingId || null as number | null, costId: null as number | null, sourceId: null as number | null, method: 'cash', reference: '', description: '', occurredOn: today })
const transaction = reactive(blankTransaction())
watch(() => props.initialBookingId, id => { if (id) { transaction.kind = 'payment'; transaction.bookingId = id; transaction.amount = (props.bookings.find(booking => booking.id === id)?.balance.outstanding || 0) / 100 } })
const blankCost = () => ({ requestKey: crypto.randomUUID(), supplier: '', description: '', category: 'direct', amount: 0, tax: 0, status: 'committed', dueDate: '', invoiceNumber: '', notes: '' })
const cost = reactive(blankCost())
const editingCostId = ref<number | null>(null)
const originalCost = ref<any>(null)
const isBooking = computed(() => ['payment', 'refund'].includes(transaction.kind)); const isCost = computed(() => ['cost_payment', 'cost_refund'].includes(transaction.kind)); const isRefund = computed(() => transaction.kind.includes('refund'))
const refundable = (row: any) => row.amount - props.ledger.filter(item => item.sourceId === row.id).reduce((sum, item) => sum + item.amount, 0)
const refundSources = computed(() => props.ledger.filter(row => row.kind === ({ refund: 'payment', income_refund: 'income', cost_refund: 'cost_payment' } as Record<string, string>)[transaction.kind] && row.bookingId === transaction.bookingId && row.costId === transaction.costId && refundable(row) > 0))
function resetLinks() { transaction.bookingId = null; transaction.costId = null; transaction.sourceId = null; transaction.tax = 0 }
function costDue(item: any) { return item.amount + item.tax - props.ledger.filter(row => row.costId === item.id).reduce((sum, row) => sum + (row.kind === 'cost_payment' ? row.amount : -row.amount), 0) }
const metrics = computed(() => { const f = props.finances; return [{ label: 'Event revenue (before tax)', value: f.revenue, description: 'Booking charges + other income' }, { label: 'Gross event profit', value: f.grossProfit, description: 'Revenue less direct costs' }, { label: 'Net event profit before tax', value: f.netProfit, description: 'After other expenses and overhead' }, { label: 'Cash surplus', value: f.cashSurplus, description: 'Receipts less refunds and supplier payments' }, { label: 'Family collections', value: f.collected, description: `Refunded ${formatMinor(f.refunds)}` }, { label: 'Family balances due', value: f.outstanding, description: 'Not yet collected' }, { label: 'Refunds / credits due', value: f.refundDue, description: 'Overpayments and cancelled booking credits' }, { label: 'Supplier balances due', value: f.supplierDue, description: `Paid ${formatMinor(f.costPaid)}` }] })
const budgetMetrics = computed(() => { const f = props.finances; return [{ label: 'Direct costs', value: formatMinor(f.directCosts) }, { label: 'Other expenses', value: formatMinor(f.overheadCosts) }, { label: 'Total budget at current attendance', value: formatMinor(f.budgetTotal) }, { label: 'Budget remaining / (overrun)', value: formatMinor(f.budgetVariance) }, { label: 'Forecast profit after remaining budget', value: formatMinor(f.forecastProfit) }, { label: 'Net profit margin', value: `${f.margin.toFixed(1)}%` }, { label: 'Estimated break-even attendance', value: f.breakEvenAttendees === null ? 'Set budget and register attendees' : `${f.breakEvenAttendees} people` }, { label: 'Tax on booking charges / income', value: formatMinor(f.outputTax) }] })
const savingTransaction = ref(false); const savingCost = ref(false); const transactionError = ref(''); const costError = ref(''); const busyCost = ref<number | null>(null)
async function saveTransaction() { savingTransaction.value = true; transactionError.value = ''; try { await $fetch(`${props.endpoint}/ledger`, { method: 'POST', body: { ...transaction, amount: Math.round(transaction.amount * 100), tax: Math.round(transaction.tax * 100) } }); Object.assign(transaction, blankTransaction()); emit('changed'); toast.add({ title: 'Transaction recorded', color: 'success' }) } catch (err: any) { transactionError.value = err.data?.statusMessage || err.message } finally { savingTransaction.value = false } }
function startCostEdit(item: any) { editingCostId.value = item.id; originalCost.value = { supplier: item.supplier, description: item.description, category: item.category, amount: item.amount, tax: item.tax, status: item.status, dueDate: item.dueDate, invoiceNumber: item.invoiceNumber, notes: item.notes }; Object.assign(cost, { ...originalCost.value, amount: item.amount / 100, tax: item.tax / 100 }) }
function cancelCostEdit() { editingCostId.value = null; originalCost.value = null; Object.assign(cost, blankCost()); costError.value = '' }
async function saveCost() { savingCost.value = true; costError.value = ''; try { const values = { ...cost, dueDate: cost.dueDate || null, amount: Math.round(cost.amount * 100), tax: Math.round(cost.tax * 100) }; const wasEditing = Boolean(editingCostId.value); if (editingCostId.value) { const changes = Object.fromEntries(Object.entries(values).filter(([key, value]) => key !== 'requestKey' && value !== originalCost.value?.[key])); await $fetch(`${props.endpoint}/costs/${editingCostId.value}`, { method: 'PATCH', body: changes }) } else await $fetch(`${props.endpoint}/costs`, { method: 'POST', body: values }); cancelCostEdit(); emit('changed'); toast.add({ title: wasEditing ? 'Cost updated' : 'Cost recorded', color: 'success' }) } catch (err: any) { costError.value = err.data?.statusMessage || err.message } finally { savingCost.value = false } }
async function setCostStatus(id: number, status: string) { if (status === 'cancelled' && !confirm('Cancel this supplier cost? Its history will remain.')) return; busyCost.value = id; try { await $fetch(`${props.endpoint}/costs/${id}`, { method: 'PATCH', body: { status } }); emit('changed') } catch (err: any) { toast.add({ title: err.data?.statusMessage || err.message, color: 'error' }) } finally { busyCost.value = null } }
</script>
<style scoped>
.finance-form label { font-size:.875rem; font-weight:500; }
.finance-form input, .finance-form select { display:block; width:100%; margin-top:.4rem; padding:.6rem .75rem; border:1px solid var(--ui-border); border-radius:.5rem; background:var(--ui-bg); color:var(--ui-text); font-weight:400; }
th, td { padding:.8rem .6rem; border-bottom:1px solid var(--ui-border); vertical-align:top; }
</style>
